import { toast } from "sonner";
import { Link } from "react-router-dom";
import { useContextSelector } from "use-context-selector";
import LoaderDotsBetter from "../../../../components/LoaderDotsBetter";
import CartQuantityControl from "../../../../components/CartQuantityControl";
import {
  BasketContext,
  AddToBasketContext,
} from "../../../../Context/BasketContext";

export function BasketControls({ product }) {
  const basketData = useContextSelector(BasketContext, (ctx) => ctx.basketData);
  const { mutate: addToBasket, loadingProducts: addLoading } =
    useContextSelector(AddToBasketContext, (ctx) => ctx);
  const quantity = basketData.find((p) => p.id === product.id)?.count || null;
  const isLoadingThisProduct = addLoading[product.id];

  if (!product?.count) return null;

  return quantity ? (
    <div className="flex justify-between items-center">
      <CartQuantityControl product={product} />
      <Link
        to={"/Cart"}
        className="bg-amber-600 dark:bg-teal-500 text-white w-40 h-13.5 flex
       justify-center items-center rounded-xl text-lg"
      >
        سبد خرید
      </Link>
    </div>
  ) : (
    <div className="flex flex-col">
      <div className="flex gap-4 mt-2">
        <button
          onClick={() => addToBasket(product?.id)}
          className="flex-1 bg-amber-600 
        text-white py-3 rounded-xl shadow-md hover:bg-amber-700 flex justify-center items-center"
        >
          {isLoadingThisProduct ? (
            <LoaderDotsBetter color="white" />
          ) : (
            "افزودن به سبد"
          )}
        </button>
        <button
          onClick={() => toast.info("خرید سریع هنوز در دسترس نیست")}
          className="flex-1 
        border border-amber-600 text-amber-600 py-3 rounded-xl hover:bg-amber-50 
        dark:hover:bg-amber-50/20 dark:hover:text-white"
        >
          خرید سریع
        </button>
      </div>
    </div>
  );
}
