import Slider from "react-slick";
import { MainSlider } from "./MainSlider";
import { useEffect, useRef } from "react";

export function GalleryModal({
  images,
  selectedIndex,
  setSelectedIndex,
  onClose,
}) {
  const thumbRef = useRef(null);
  const mainSliderRef = useRef(null);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "Escape") {
        onClose();
      }
      if (e.key === "ArrowRight" && selectedIndex < images.length - 1) {
        const next = selectedIndex + 1;
        setSelectedIndex(next);
        mainSliderRef.current?.slickGoTo(next);
      }
      if (e.key === "ArrowLeft" && selectedIndex > 0) {
        const prev = selectedIndex - 1;
        setSelectedIndex(prev);
        mainSliderRef.current?.slickGoTo(prev);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [selectedIndex, images.length, onClose,setSelectedIndex]);

  return (
    <div
      className="fixed inset-0 bg-black bg-opacity-70 flex flex-col items-center justify-center
     z-50 p-4"
    >
      <button
        className="absolute top-4 right-4 text-white text-3xl font-bold z-50 cursor-pointer"
        onClick={onClose}
      >
        ✕
      </button>

      <div className="bg-white dark:bg-zinc-700 w-full max-w-4xl rounded-xl p-4 relative">
        <MainSlider
          images={images}
          selectedIndex={selectedIndex}
          setSelectedIndex={setSelectedIndex}
          sliderRef={mainSliderRef} // اضافه شده
        />
      </div>

      <div
        className="flex flex-row-reverse bg-white dark:bg-zinc-700 rounded-xl mt-6 py-3 px-2
       max-w-4xl"
      >
        <Slider
          {...{
            dots: false,
            arrows: false,
            infinite: false,
            slidesToShow: Math.min(images.length, 6),
            slidesToScroll: 1,
            focusOnSelect: true,
            swipeToSlide: true,
            centerMode: true,
            centerPadding: "0px",
          }}
          ref={thumbRef}
        >
          {images.map((img, index) => (
            <div key={index} className="px-1">
              <img
                src={img}
                alt={`تصویر ${index + 1}`}
                className={`w-20 h-20 object-contain rounded-lg cursor-pointer border-2 ${
                  selectedIndex === index
                    ? "border-blue-500 shadow-lg"
                    : "border-gray-300"
                }`}
                onClick={() => {
                  setSelectedIndex(index);
                  mainSliderRef.current?.slickGoTo(index); // اسلاید اصلی هم بروزرسانی شود
                }}
              />
            </div>
          ))}
        </Slider>
      </div>
    </div>
  );
}
