import { ChevronLeftIcon, ChevronRightIcon } from "@heroicons/react/24/outline";

export const PrevArrow = ({ onClick, disabled }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    className={`absolute left-[-3rem] top-1/2 -translate-y-1/2 w-14 h-14 flex items-center
     justify-center rounded-full shadow-lg z-20 text-3xl transition 
     ${
       disabled
         ? "bg-gray-300 text-gray-500 cursor-not-allowed"
         : "bg-white text-black hover:bg-gray-200"
     }`}
  >
    <ChevronLeftIcon className="w-7 h-7" />
  </button>
);

export const NextArrow = ({ onClick, disabled }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    className={`absolute right-[-3rem] top-1/2 -translate-y-1/2 w-14 h-14 flex items-center 
    justify-center rounded-full shadow-lg z-20 text-3xl transition
    ${
      disabled
        ? "bg-gray-300 text-gray-500 cursor-not-allowed"
        : "bg-white text-black hover:bg-gray-200"
    }`}
  >
    <ChevronRightIcon className="w-7 h-7" />
  </button>
);
