import Slider from "react-slick";
import { useState, useEffect } from "react";

export function ThumbnailSlider({ images, selectedIndex, onSelect, onOpen }) {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    setReady(true); // بعد از mount Slider را فعال کن
  }, []);

  const settings = {
    dots: false,
    arrows: false,
    infinite: false,
    slidesToShow: Math.min(images.length, 5),
    slidesToScroll: 1,
    focusOnSelect: true,
    swipeToSlide: true,
    rtl: true,
  };

  if (!ready) return null; // تا mount نشدن چیزی render نشه

  return (
    <div className="w-full max-w-[400px]">
      <Slider {...settings}>
        {images.map((img, index) => (
          <div key={index} className="px-1">
            <img
              src={img}
              alt={`تصویر ${index + 1}`}
              className={`w-20 h-20 object-contain rounded-lg cursor-pointer border-2 ${
                selectedIndex === index ? "border-blue-500 shadow-md" : "border-transparent"
              }`}
              onClick={() => onOpen()}
            />
          </div>
        ))}
      </Slider>
    </div>
  );
}
